parameters.text:
={{ (() => {
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const e = $json.execution || {};
return `🚨 Workflow failed

Workflow: ${esc($json.workflow?.name)}
Failed node: ${esc(e.lastNodeExecuted || 'unknown (trigger-level error)')}
Error: ${esc(e.error?.message || 'no message')}

Execution: ${esc(e.id || 'n/a')}
${esc(e.url || '')}

If this was a ticket, the customer may not have received a reply.`;
})() }}
